(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const sx1 = x+w1x, sy1 = y+w1y;
  const w2x = Math.sin(sx1*0.03+t*0.5)*8+Math.cos(sy1*0.025-t*0.4)*6;
  const w2y = Math.cos(sy1*0.028-t*0.45)*8+Math.sin(sx1*0.022+t*0.55)*6;
  const sx = sx1+w2x, sy = sy1+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [200+Math.sin(t*0.7+3)*60,100+Math.cos(t*0.6+2)*40,0.15,3.0],
    [280+Math.cos(t*0.45+1)*70,150+Math.sin(t*0.65+4)*50,0.13,2.8]
  ];
  let aS=0,iS=0,eS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const pulse=0.7+0.3*Math.sin(t*sp*0.8+sX*0.01);
    aS+=Math.sin(d*f-t*sp)*pulse;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*pulse;
    eS+=Math.cos(d*f*1.3-t*sp*0.4+2.0)*pulse*0.5;
  }
  const act=aS/8,inh=iS/8,exc=eS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.08+t*1.5)*Math.sin(sy*0.07-t*1.3)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08-ang*2-t*2.0)*0.2;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const rd2=Math.tanh((rd1*1.3+exc*0.4+Math.sin(sx*0.06-sy*0.05+t*0.9)*0.5-Math.cos(sx*0.04+sy*0.07-t*0.7)*0.3)*1.8);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(sx*0.4+t*2)*Math.sin(sy*0.35-t*1.8)*0.08;
  const blend=rd2*0.55+cell*0.2+rd1*0.15+micro, v=blend*0.5+0.5;
  const pal=[
    [4,8,42],[8,28,72],[12,55,105],[18,90,130],[25,135,145],
    [60,170,135],[140,190,90],[210,185,65],[225,145,55],
    [205,95,60],[155,50,65],[85,25,55],[30,12,48],[4,8,42]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.82+Math.sin(rd2*Math.PI)*0.18;
  const edge=Math.abs(rd2)>0.65?1.18:1.0;
  const shimmer=1.0+Math.sin(sx*0.25+sy*0.2+t*3.5)*0.04;
  const glow=1.0+Math.max(0,rd2-0.3)*0.15;
  const m=lum*edge*shimmer*glow;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
